<header class="admin-page-head"><div><span class="eyebrow">پرداخت موقت</span><h1>بررسی رسیدهای کارت‌به‌کارت</h1><p>تصویر رسید و گردش حساب بانکی را تطبیق دهید، سپس نتیجه را ثبت کنید.</p></div></header>
<?php if($notice): ?><p class="alert" role="status"><?= e($notice) ?></p><?php endif; ?>
<nav class="admin-tabs manual-admin-tabs" aria-label="وضعیت رسیدها"><?php foreach(['pending'=>'منتظر بررسی','approved'=>'تأییدشده','rejected'=>'ردشده'] as $key=>$label): ?><a class="<?= $status===$key?'is-active':'' ?>" href="/admin/manual-payments?status=<?= e($key) ?>"><?= e($label) ?> (<?= (int)(array_column($counts,'total','status')[$key]??0) ?>)</a><?php endforeach; ?></nav>
<?php if(!$ready): ?><p class="alert">SQL شماره ۰۱۲ را نصب کنید.</p><?php endif; ?>
<div class="manual-admin-grid"><?php foreach($items as $item): ?><article class="admin-panel"><header><h2><?= e($item['name']) ?></h2><span class="badge">بخش <?= (int)$item['part'] ?></span></header><h3><?= e($item['item_title']) ?></h3><p><strong><?= number_format((int)$item['amount']) ?> تومان</strong></p><a href="/payments/receipt/<?= e($item['id']) ?>" target="_blank" rel="noopener"><img class="manual-receipt-preview" src="/payments/receipt/<?= e($item['id']) ?>" alt="رسید پرداخت برای بررسی" loading="lazy"></a><?php if(!empty($item['discount'])): ?><p class="payment-discount-summary">کد <strong dir="ltr"><?= e($item['discount']['code']) ?></strong> · تخفیف کل <?= number_format((int)$item['discount']['discount_amount']) ?> تومان</p><?php endif; ?><small><?= e($item['updated_at']) ?> UTC</small>
<?php if($item['status']==='pending'): ?><form class="stack" method="post" action="/admin/manual-payments/<?= e($item['id']) ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$item['version'] ?>"><label class="form-group"><span class="form-label">توضیح نتیجه (اختیاری)</span><textarea class="form-control" name="note" rows="2" maxlength="1000"></textarea></label><div class="cluster"><button class="btn btn--primary" name="status" value="approved">تأیید دریافت وجه</button><button class="btn btn--secondary" name="status" value="rejected">رد رسید</button></div></form><?php else: ?><p><?= e($item['review_note']) ?></p><?php endif; ?></article><?php endforeach; ?></div>
<?php if(!$items): ?><div class="admin-panel">رسیدی با این وضعیت وجود ندارد.</div><?php endif; ?><nav class="cluster mt-6"><?php if($page>1): ?><a class="btn btn--secondary" href="?status=<?= e($status) ?>&amp;page=<?= $page-1 ?>">قبلی</a><?php endif; ?><?php if(count($items)===20): ?><a class="btn btn--secondary" href="?status=<?= e($status) ?>&amp;page=<?= $page+1 ?>">بعدی</a><?php endif; ?></nav>
